import os
from datetime import datetime

import pytest
from fastapi.testclient import TestClient

from app.auth.principal import MEMBER
from app.auth.tokens import AccessTokens
from app.bookings.service import BookingService
from app.config import get_settings
from app.deps import get_booking_service, get_conn
from app.main import create_app
from app.rooms.models import Room
from tests.fakes import InMemoryBookingRepository, InMemoryRoomRepository

NOW = datetime.fromisoformat("2026-10-01T09:00:00Z")
TEST_SECRET = "cm9vbWJvb2stdGVzdC1vbmx5LXNpZ25pbmcta2V5ISE"
TEST_ENV = {
    "HU_FIXED_TIME": "2026-10-01T09:00:00Z",
    "JWT_SECRET": TEST_SECRET,
    "DATABASE_URL": os.environ.get("TEST_DATABASE_URL", "postgresql://localhost/roombook_test"),
}
ROOMS = [
    Room(1, "Turing", "main-library", 6, ["whiteboard", "screen"]),
    Room(2, "Lovelace", "main-library", 4, ["whiteboard"]),
]


@pytest.fixture
def anyio_backend():
    return "asyncio"


@pytest.fixture
def rooms() -> InMemoryRoomRepository:
    return InMemoryRoomRepository(ROOMS)


@pytest.fixture
def bookings() -> InMemoryBookingRepository:
    return InMemoryBookingRepository(lambda: NOW)


@pytest.fixture
def app(monkeypatch):
    """A fresh app for each test, built by create_app() from test settings."""
    for name, value in TEST_ENV.items():
        monkeypatch.setenv(name, value)
    get_settings.cache_clear()
    return create_app()


@pytest.fixture
def client(app, rooms, bookings):
    """A client for the app with in-memory repositories. No server, no database."""
    app.dependency_overrides[get_booking_service] = lambda: BookingService(bookings, rooms, lambda: NOW)
    app.dependency_overrides[get_conn] = lambda: None
    return TestClient(app)


@pytest.fixture
def ada_auth():
    """An Authorization header for Ada, signed the way the app signs tokens."""
    token = AccessTokens(TEST_SECRET).issue(1, "member", None, MEMBER)
    return {"Authorization": f"Bearer {token}"}
